CREATE TABLE IF NOT EXISTS schema_version (version INT NOT NULL);
CREATE TABLE IF NOT EXISTS accounts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(24) NOT NULL UNIQUE, pass_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, last_login TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sessions (token_hash CHAR(64) PRIMARY KEY, account_id BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, expires_at DATETIME NOT NULL, FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE CASCADE, INDEX (account_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS ratings (account_id BIGINT UNSIGNED PRIMARY KEY, elo INT NOT NULL DEFAULT 1000, matches INT NOT NULL DEFAULT 0, wins INT NOT NULL DEFAULT 0, FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE CASCADE, INDEX (elo)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS matches (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, started_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, ended_at TIMESTAMP NULL, map VARCHAR(64) NULL, ranked TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS match_players (match_id BIGINT UNSIGNED NOT NULL, account_id BIGINT UNSIGNED NOT NULL, placement INT NOT NULL, survival_secs INT NOT NULL DEFAULT 0, tile_share FLOAT NOT NULL DEFAULT 0, left_early TINYINT(1) NOT NULL DEFAULT 0, elo_before INT NOT NULL, elo_after INT NOT NULL, PRIMARY KEY (match_id, account_id), FOREIGN KEY (match_id) REFERENCES matches(id) ON DELETE CASCADE, FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS progress (account_id BIGINT UNSIGNED PRIMARY KEY, data JSON NOT NULL, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS mc_links (account_id BIGINT UNSIGNED PRIMARY KEY, mc_uuid CHAR(36) NOT NULL UNIQUE, linked_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS link_codes (code VARCHAR(16) PRIMARY KEY, account_id BIGINT UNSIGNED NOT NULL, kind ENUM('link','recover') NOT NULL, expires_at DATETIME NOT NULL, used TINYINT(1) NOT NULL DEFAULT 0, consumed TINYINT(1) NOT NULL DEFAULT 0, FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS guest_counter (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, issued_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
INSERT INTO schema_version SELECT 4 WHERE NOT EXISTS (SELECT 1 FROM schema_version);

-- Version 5 preserves existing free-for-all rows with a NULL team.
ALTER TABLE match_players ADD COLUMN IF NOT EXISTS team INT NULL;
UPDATE schema_version SET version = 5 WHERE version = 4;
